const MODEL = $env.CLAUDE_MODEL || 'claude-opus-5-5';
const EFFORT = $env.CLAUDE_EFFORT || 'low';

function claudeRequest(system, userText, schema, maxTokens = 16000) {
  return {
    model: MODEL,
    max_tokens: maxTokens,
    system,
    fallbacks: 'default',
    output_config: { effort: EFFORT, format: { type: 'json_schema', schema } },
    messages: [{ role: 'user', content: userText }],
  };
}

function parseClaude(resp) {
  if (!resp || resp.error) throw new Error('API error: ' + JSON.stringify(resp && resp.error).slice(0, 500));
  if (resp.stop_reason === 'refusal') throw new Error('refused: ' + JSON.stringify(resp.stop_details));
  if (resp.stop_reason === 'max_tokens') throw new Error('output truncated at max_tokens');
  const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
  return JSON.parse(text);
}

const SYSTEM = "You analyze consumer posts and product reviews to find unmet, purchasable product demand.\n\nFor each signal you receive (each has a numeric signal_id), decide whether it expresses a real\nproduct need: a problem the person would pay a physical or digital product to solve, or an explicit\nrequest for a recommendation or a place to buy something.\n\nRules:\n- Return exactly one item per signal_id you were given, in any order.\n- Set is_demand to false for news, jokes, politics, job posts, and anything that is not about\n  buying or using a physical product. Services are out of scope too: restaurants, healthcare,\n  trades and contractors, financial products, insurance, travel, events, real estate and\n  subscriptions. For those items, fill the text fields with empty strings and set intent_level to 1.\n- cluster_key: a short lowercase English slug (2 to 4 words joined by hyphens) naming the underlying\n  need, not a brand. Reuse the same slug for the same need, for example \"car-hail-protection\" or\n  \"dog-paw-salt-protection\".\n- pain: one sentence in English describing the problem in the person's terms.\n- context: when and where it happens (season, activity, place).\n- audience: who has this problem.\n- quote: the most telling phrase copied verbatim from the signal, at most 200 characters. Never invent it.\n- intent_level: 1 = vague complaint, 2 = recurring frustration, 3 = actively looking for a solution,\n  4 = asking where to buy or for a recommendation, 5 = says they will pay or names a budget.\n- product_hint: the kind of product that would solve it, generic and without brands.\n- geo: the most specific place mentioned or implied (for example \"calgary\", \"alberta\", \"canada\"),\n  or an empty string.";
const SCHEMA = {"type": "object", "properties": {"items": {"type": "array", "items": {"type": "object", "properties": {"signal_id": {"type": "integer"}, "is_demand": {"type": "boolean"}, "cluster_key": {"type": "string"}, "pain": {"type": "string"}, "context": {"type": "string"}, "audience": {"type": "string"}, "quote": {"type": "string"}, "intent_level": {"type": "integer"}, "product_hint": {"type": "string"}, "geo": {"type": "string"}}, "required": ["signal_id", "is_demand", "cluster_key", "pain", "context", "audience", "quote", "intent_level", "product_hint", "geo"], "additionalProperties": false}}}, "required": ["items"], "additionalProperties": false};

const signals = $input.all().map(i => i.json).filter(s => s.id);
const CHUNK = 10;
const out = [];
for (let i = 0; i < signals.length; i += CHUNK) {
  const chunk = signals.slice(i, i + CHUNK).map(s => ({
    signal_id: Number(s.id), source: s.source, geo_hint: s.geo_hint,
    title: s.title, body: String(s.body || '').slice(0, 2000),
  }));
  out.push({ json: {
    signal_ids: chunk.map(s => s.signal_id),
    request: claudeRequest(SYSTEM, 'Signals:\n' + JSON.stringify(chunk, null, 1), SCHEMA),
  }});
}
return out;

const MODEL = $env.CLAUDE_MODEL || 'claude-opus-5-5';
const EFFORT = $env.CLAUDE_EFFORT || 'low';

function claudeRequest(system, userText, schema, maxTokens = 16000) {
  return {
    model: MODEL,
    max_tokens: maxTokens,
    system,
    fallbacks: 'default',
    output_config: { effort: EFFORT, format: { type: 'json_schema', schema } },
    messages: [{ role: 'user', content: userText }],
  };
}

function parseClaude(resp) {
  if (!resp || resp.error) throw new Error('API error: ' + JSON.stringify(resp && resp.error).slice(0, 500));
  if (resp.stop_reason === 'refusal') throw new Error('refused: ' + JSON.stringify(resp.stop_details));
  if (resp.stop_reason === 'max_tokens') throw new Error('output truncated at max_tokens');
  const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
  return JSON.parse(text);
}

const reqs = $('Build Claude Requests').all();
const rows = [], done = [], errors = [];
const clean = (s, n) => String(s || '').trim().slice(0, n);
$input.all().forEach((item, i) => {
  const ids = (reqs[i] && reqs[i].json.signal_ids) || [];
  try {
    const out = parseClaude(item.json);
    const valid = new Set(ids);
    for (const p of out.items || []) {
      if (!valid.has(p.signal_id) || !p.is_demand) continue;
      const key = clean(p.cluster_key, 60).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
      if (!key || !p.pain) continue;
      rows.push({
        signal_id: p.signal_id, cluster_key: key, pain: clean(p.pain, 500),
        context: clean(p.context, 500), audience: clean(p.audience, 300), quote: clean(p.quote, 200),
        intent_level: Math.min(5, Math.max(1, Math.round(Number(p.intent_level) || 1))),
        product_hint: clean(p.product_hint, 200), geo: clean(p.geo, 60).toLowerCase(),
      });
    }
    done.push(...ids);  // 只有成功解析的批次才标记为已处理，失败的下次重试
  } catch (e) {
    errors.push({ signal_ids: ids, error: String(e.message || e).slice(0, 500) });
  }
});
return [{ json: { rows, done, errors } }];
